/**
 * Form fields (design.punji.app/components/field): a label over a boxed
 * input, a hint or an error under it. NumberField accepts grouping commas
 * and Devanagari digits; DateField is the native date input; SymbolField is a
 * combobox over a list the page hands it (no request per keystroke).
 */
import { useId, useMemo, useState, type InputHTMLAttributes, type ReactNode, type TextareaHTMLAttributes } from 'react';

import { Select } from '../select/Select.tsx';
import { searchSymbols, type SymbolOption } from '../format/format.ts';

interface BaseProps {
  label: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  testId?: string;
  /** The box: lg 44 (forms, the default) or md 36 (a toolbar). */
  size?: 'md' | 'lg';
  /** Keeps the label for screen readers only (a toolbar field whose purpose the row already shows). */
  hideLabel?: boolean;
}

type InputProps = BaseProps & Omit<InputHTMLAttributes<HTMLInputElement>, 'onChange' | 'value' | 'size'> & {
  value: string;
  onChange: (v: string) => void;
};

function Shell({ id, label, hint, error, size = 'lg', hideLabel, children }: BaseProps & { id: string; children: ReactNode }) {
  return (
    <div className={`kit-field${size === 'md' ? ' md' : ''}`} data-invalid={error ? 'true' : undefined}>
      <label htmlFor={id} className={hideLabel ? 'kit-sr' : undefined}>{label}</label>
      {children}
      {error ? (
        <span className="err" id={`${id}-err`} role="alert">{error}</span>
      ) : hint ? (
        <span className="hint" id={`${id}-hint`}>{hint}</span>
      ) : null}
    </div>
  );
}

export function Field({ label, hint, error, testId, value, onChange, id: idProp, size, hideLabel, ...rest }: InputProps) {
  const auto = useId();
  const id = idProp ?? auto;
  return (
    <Shell id={id} label={label} hint={hint} error={error} size={size} hideLabel={hideLabel}>
      <input
        {...rest}
        id={id}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? `${id}-err` : hint ? `${id}-hint` : undefined}
        data-testid={testId}
      />
    </Shell>
  );
}

export function NumberField({ integer, ...props }: InputProps & { integer?: boolean }) {
  return <Field {...props} inputMode={integer ? 'numeric' : 'decimal'} autoComplete="off" />;
}

/** Several lines of text (a message, a note): the same box, at least two control heights tall, grows with `rows`. */
export function TextAreaField({ label, hint, error, testId, value, onChange, id: idProp, size, hideLabel, rows = 4, ...rest }: BaseProps & Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, 'onChange' | 'value' | 'size'> & { value: string; onChange: (v: string) => void }) {
  const auto = useId();
  const id = idProp ?? auto;
  return (
    <Shell id={id} label={label} hint={hint} error={error} size={size} hideLabel={hideLabel}>
      <textarea
        {...rest}
        id={id}
        rows={rows}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? `${id}-err` : hint ? `${id}-hint` : undefined}
        data-testid={testId}
      />
    </Shell>
  );
}

export function DateField(props: InputProps) {
  return <Field {...props} type="date" />;
}

export function SelectField({ label, hint, error, testId, value, onChange, options, size, hideLabel }: BaseProps & { value: string; onChange: (v: string) => void; options: { value: string; label: string }[] }) {
  const id = useId();
  return (
    <Shell id={id} label={label} hint={hint} error={error} size={size} hideLabel={hideLabel}>
      <Select id={id} block value={value} onChange={onChange} options={options} testId={testId} aria-invalid={error ? true : undefined} aria-describedby={error ? `${id}-err` : hint ? `${id}-hint` : undefined} />
    </Shell>
  );
}

export function SymbolField({ label, hint, error, testId, value, onChange, options, placeholder, size, hideLabel }: BaseProps & { value: string; onChange: (v: string) => void; options: readonly SymbolOption[]; placeholder?: string }) {
  const id = useId();
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const matches = useMemo(() => searchSymbols(options, value), [options, value]);
  const show = open && matches.length > 0 && !(matches.length === 1 && matches[0]?.symbol === value.toUpperCase());
  const pick = (o: SymbolOption) => {
    onChange(o.symbol);
    setOpen(false);
  };
  return (
    <Shell id={id} label={label} hint={hint} error={error} size={size} hideLabel={hideLabel}>
      <input
        id={id}
        role="combobox"
        aria-expanded={show}
        aria-controls={`${id}-list`}
        aria-autocomplete="list"
        aria-activedescendant={show ? `${id}-opt-${active}` : undefined}
        aria-invalid={error ? true : undefined}
        autoComplete="off"
        autoCapitalize="characters"
        spellCheck={false}
        placeholder={placeholder}
        value={value}
        onChange={(e) => {
          onChange(e.target.value.toUpperCase());
          setOpen(true);
          setActive(0);
        }}
        onFocus={() => setOpen(true)}
        onBlur={() => setTimeout(() => setOpen(false), 120)}
        onKeyDown={(e) => {
          if (!show) return;
          if (e.key === 'ArrowDown') {
            e.preventDefault();
            setActive((a) => Math.min(a + 1, matches.length - 1));
          } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            setActive((a) => Math.max(a - 1, 0));
          } else if (e.key === 'Enter') {
            e.preventDefault();
            const hit = matches[active];
            if (hit) pick(hit);
          } else if (e.key === 'Escape') {
            setOpen(false);
          }
        }}
        data-testid={testId}
      />
      {show && (
        <ul className="kit-options" id={`${id}-list`} role="listbox">
          {matches.map((o, i) => (
            <li
              key={o.symbol}
              id={`${id}-opt-${i}`}
              role="option"
              aria-selected={i === active}
              onMouseDown={(e) => {
                e.preventDefault();
                pick(o);
              }}
              data-testid={`symbol-option-${o.symbol}`}
            >
              <b>{o.symbol}</b>
              <span>{o.name}</span>
            </li>
          ))}
        </ul>
      )}
    </Shell>
  );
}

/** An editable price with an optional source annotation, isolated from ordinary number fields. */
export function PriceField({ label, source, hint, error, testId, value, onChange, id: idProp, size, hideLabel, ...rest }: InputProps & { /** A compact source annotation inside the editable price. */ source?: ReactNode }) {
  const auto = useId();
  const id = idProp ?? auto;
  return (
    <Shell id={id} label={label} hint={hint} error={error} size={size} hideLabel={hideLabel}>
      <input
        {...rest}
        inputMode="decimal"
        autoComplete="off"
        id={id}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? `${id}-err` : hint ? `${id}-hint` : undefined}
        data-testid={testId}
      />
      {source && <span className="kit-field-suffix">{source}</span>}
    </Shell>
  );
}
